SELECT CASE WHEN city IN ('New York', 'Singapore') THEN 'group_a' ELSE 'other' END AS city_group, CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END AS rating_bucket, city, MIN(rating) AS min_rating, SUM(rating) AS total_rating FROM suppliers WHERE UPPER(TRIM(supplier_name)) = 'PACIFIC WHOLESALE' GROUP BY CASE WHEN city IN ('New York', 'Singapore') THEN 'group_a' ELSE 'other' END, CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.7 THEN 'mid' ELSE 'low' END, city HAVING min_rating >= 2.6
